#!/usr/bin/env python3
"""Inspect report.pdf: existence, page count, metadata, and page sizes."""
import sys
from pypdf import PdfReader

def main() -> int:
    try:
        reader = PdfReader("report.pdf")
    except Exception as exc:  # pragma: no cover - error reporting
        print(f"ERROR opening report.pdf: {exc}", file=sys.stderr)
        return 1

    print(f"pages: {len(reader.pages)}")
    meta = reader.metadata
    if meta:
        for key in ("title", "author", "subject", "creator", "producer"):
            val = getattr(meta, key, None)
            if val:
                print(f"meta.{key}: {val}")
    for i, page in enumerate(reader.pages):
        box = page.mediabox
        print(f"page {i + 1}: {float(box.width):.1f} x {float(box.height):.1f}")
    return 0

if __name__ == "__main__":
    sys.exit(main())

